const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const windhoek = ee.Geometry.Point([17.08, -22.57]);
  const region = windhoek.buffer(50000); // 50km buffer around Windhoek

  const date1 = '2020-01-29';
  const date2 = '2021-02-07';

  // 2. Data Acquisition & Check
  // Try Sentinel-2 first
  let col2020 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));

  let col2021 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));

  const size2020 = await col2020.size().getInfo();
  const size2021 = await col2021.size().getInfo();

  console.log(`2020 Sentinel-2 Images: ${size2020}`);
  console.log(`2021 Sentinel-2 Images: ${size2021}`);

  // Fallback to Landsat 8 if needed
  if (size2020 === 0 || size2021 === 0) {
    console.log('Falling back to Landsat 8...');
    col2020 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(region)
      .filterDate(date1, ee.Date(date1).advance(1, 'day'));

    col2021 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(region)
      .filterDate(date2, ee.Date(date2).advance(1, 'day'));

    const ls_size2020 = await col2020.size().getInfo();
    const ls_size2021 = await col2021.size().getInfo();

    console.log(`2020 Landsat 8 Images: ${ls_size2020}`);
    console.log(`2021 Landsat 8 Images: ${ls_size2021}`);

    if (ls_size2020 === 0 || ls_size2021 === 0) {
      console.log('No data available for comparison.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Cloud masking and NDVI calculation
  function maskS2clouds(image) {
    const scl = image.select('SCL');
    const mask = scl.neq(3).and(scl.neq(8)).and(scl.neq(9)).and(scl.neq(10));
    return image.updateMask(mask);
  }

  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  const img2020 = col2020.map(maskS2clouds).map(addNDVI).median();
  const img2021 = col2021.map(maskS2clouds).map(addNDVI).median();

  // Check pixel counts
  const count2020 = await img2020.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const count2021 = await img2021.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`2020 Valid Pixels: ${count2020}`);
  console.log(`2021 Valid Pixels: ${count2021}`);

  if (count2020 === 0 || count2021 === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation
  const ndvi2020 = await img2020.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const ndvi2021 = await img2021.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // 5. Validation & Final Answer
  console.log(`2020-01-29 Mean NDVI: ${ndvi2020?.toFixed(3)}`);
  console.log(`2021-02-07 Mean NDVI: ${ndvi2021?.toFixed(3)}`);

  if (ndvi2020 === null || ndvi2021 === null || 
      isNaN(ndvi2020) || isNaN(ndvi2021) ||
      ndvi2020 < -1 || ndvi2020 > 1 ||
      ndvi2021 < -1 || ndvi2021 > 1) {
    console.log('Invalid NDVI calculation.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (ndvi2021 > ndvi2020) {
    console.log(`2021 was greener (NDVI: ${ndvi2021.toFixed(3)} vs ${ndvi2020.toFixed(3)})`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`2021 was not greener (NDVI: ${ndvi2021.toFixed(3)} vs ${ndvi2020.toFixed(3)})`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
